import {prepareMemoryCard,prepareTripBook,prepareGeotaggedCopy} from './export-media.js';
import {visitView,visitsOf} from './visits.js';
import {saveBackupFile,transferCancelled} from './backup-file.js';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function createExportsUI({document,getState,device,plugin,picker,download,onStatus=()=>{}}){
 const $=id=>document.getElementById(id);let target=null,pending=null,previewUrl=null,abort=null,busy=false,committing=false,generation=0;
 function clear(){pending=null;$('export-status').textContent='';$('export-preview').removeAttribute('src');$('export-save').disabled=true;$('export-preview').hidden=true;if(previewUrl){URL.revokeObjectURL(previewUrl);previewUrl=null;}}
 function options(){return {title:$('export-title').value,location:$('export-location').value,includeDate:$('export-date').checked,includeNotes:$('export-notes').checked,allPhotos:$('export-all-photos').checked};}
 function sync(){const trip=target?.kind==='trip',geotag=target?.kind==='geotag';$('export-trip-field').hidden=!trip;$('export-privacy-options').hidden=geotag;$('export-title-field').hidden=geotag;$('export-all-photos-field').hidden=!trip;$('export-controls').inert=busy;$('export-cancel-work').hidden=!busy;$('export-prepare').disabled=busy||trip&&!$('export-trip').value;$('export-save').disabled=busy||!pending;$('export-heading').textContent=geotag?'Geotagged photo copy.':trip?'Trip memory book.':'Share a memory.';$('export-intro').textContent=geotag?'Create a new JPEG copy with this visit’s coordinates. The saved original stays unchanged. Other original metadata is removed; large photos are resized to at most 4096 pixels.':'Choose what appears, prepare a preview, then save a file. Titles and stories can name a location even when address and coordinates are hidden.';}
 function reset(){generation++;abort?.abort();abort=null;busy=false;committing=false;clear();target=null;}
 async function prepare(){if(busy)return;clear();busy=true;abort=new AbortController();const token=++generation;sync();$('export-status').textContent='Preparing locally…';try{const {records,journeys}=getState();let result;
  if(target.kind==='trip'){const journey=journeys.find(j=>j.id===$('export-trip').value&&!j.deleted);if(!journey)throw Error('Choose an available journey.');result=await prepareTripBook(journey,records,options(),{signal:abort.signal,onProgress:(done,total,pages)=>{$('export-status').textContent=`Preparing visit ${done} of ${total} · ${pages} pages`;}});}else{const record=records.find(r=>r.id===target.recordId);if(!record)throw Error('This place is no longer available.');const view=visitView(record,target.visitId);result=target.kind==='geotag'?await prepareGeotaggedCopy(view,{signal:abort.signal}):await prepareMemoryCard(view,options(),abort.signal);}
  if(token!==generation)return;pending=result;const image=result.preview??(result.mimeType.startsWith('image/')?result.blob:null);if(image){previewUrl=URL.createObjectURL(image);$('export-preview').src=previewUrl;$('export-preview').hidden=false;}$('export-status').textContent=`Ready: ${result.name} · ${(result.blob.size/1024/1024).toFixed(2)} MB${result.pages?` · ${result.pages} pages. Preview shows the first page.`:''}`;
 }catch(error){if(token===generation)$('export-status').textContent=error.message==='CANCELLED'?'Preparation cancelled. Your journal is unchanged.':error.message;}finally{if(token===generation){busy=false;abort=null;sync();}}}
 async function save(){if(busy||!pending)return;busy=true;committing=false;abort=new AbortController();sync();try{const result=await saveBackupFile(pending.blob,pending.name,{native:device.native,plugin,picker,download,signal:abort.signal,mimeType:pending.mimeType,extension:pending.extension,description:pending.description,onProgress:({phase,written,total})=>{$('export-status').textContent=phase==='choosing'?'Choose where to save your file.':phase==='finalizing'?'Finishing the file…':`Saving · ${Math.round(written/total*100)}%`;},onCommit:()=>{committing=true;$('export-cancel-work').disabled=true;}});$('export-status').textContent=result.confirmed?`Saved ${result.name}.`:'Download requested. Check your browser Downloads to confirm the file.';}catch(error){$('export-status').textContent=transferCancelled(error)?'Save cancelled. Your journal is unchanged.':error.message;}finally{busy=false;committing=false;abort=null;$('export-cancel-work').disabled=false;sync();}}
 function wire(){for(const id of ['export-title','export-location','export-date','export-notes','export-all-photos'])$(id).addEventListener('input',()=>{if(!busy)clear();});$('export-trip').onchange=()=>{const j=getState().journeys.find(j=>j.id===$('export-trip').value&&!j.deleted);$('export-title').value=j?.title??'';clear();sync();};$('export-prepare').onclick=()=>void prepare();$('export-save').onclick=()=>void save();$('export-cancel-work').onclick=()=>{if(!committing)abort?.abort();};}
 return {wire,hasPending:()=>busy,open(next){reset();target=next;$('export-location').value='none';$('export-date').checked=true;$('export-notes').checked=true;$('export-all-photos').checked=true;$('export-trip').innerHTML=getState().journeys.filter(j=>!j.deleted).map(j=>`<option value="${esc(j.id)}">${esc(j.title)}</option>`).join('');if(next.tripId)$('export-trip').value=next.tripId;const record=getState().records.find(r=>r.id===next.recordId);if(next.kind==='trip')$('export-title').value=getState().journeys.find(j=>j.id===$('export-trip').value)?.title??'';else $('export-title').value=record?.title??'A memory';$('export-status').textContent='';sync();},canClose(){if(committing){onStatus('Finishing your file. Please wait.');return false;}if(busy){abort?.abort();onStatus('Cancelling the export safely. Please wait.');return false;}return true;},reset};
}
